"use strict";

function headerValue(response, name) {
  if (response.headers && typeof response.headers.get === "function") {
    return response.headers.get(name);
  }
  if (response.headers && typeof response.headers.get === "undefined") {
    return response.headers[name.toLowerCase()] || response.headers[name] || "";
  }
  return "";
}

function fallbackResponse(body, headers) {
  return {
    headers,
    text() {
      return Promise.resolve(body);
    },
  };
}

module.exports = async function fetchFallbackProbe() {
  const response = typeof Response === "function"
    ? new Response("safe", { headers: { "x-mode": "fixture" } })
    : fallbackResponse("safe", { "x-mode": "fixture" });
  const text = await response.text();
  const mode = headerValue(response, "x-mode");
  return {
    ok: text === "safe" && mode === "fixture",
    summary: "fetch:wrapper/" + text + "/" + mode,
  };
};
